6	use Illuminate\Foundation\Configuration\Middleware;
7	use Illuminate\Http\Request;
8	use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface;
9	use Symfony\Component\HttpKernel\Exception\MethodNotAllowedHttpException;
10	use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
11	
12	return Application::configure(basePath: dirname(__DIR__))
13	    ->withRouting(
14	        web: __DIR__.'/../routes/web.php',
15	        api: __DIR__.'/../routes/api.php',
16	        apiPrefix: 'api',
17	        commands: __DIR__.'/../routes/console.php',
18	    )
19	    ->withMiddleware(function (Middleware $middleware): void {
20	        $middleware->alias(['mealie' => MealieAuth::class]);
21	        // FastAPI does not redirect /api/foo/ to /api/foo; keep trailing slashes as-is.
22	        $middleware->remove(\Illuminate\Foundation\Http\Middleware\TrimStrings::class);
23	        $middleware->remove(\Illuminate\Foundation\Http\Middleware\ConvertEmptyStringsToNull::class);
24	    })
25	    ->withExceptions(function (Exceptions $exceptions): void {
26	        // Match FastAPI/Starlette's default bodies for routing errors.
27	        $exceptions->render(function (NotFoundHttpException $e, Request $request) {
28	            $message = $e->getMessage();
29	
30	            return response()->json(['detail' => $message !== '' && ! str_starts_with($message, 'The route ') ? $message : 'Not Found'], 404);
31	        });
32	        $exceptions->render(function (MethodNotAllowedHttpException $e, Request $request) {
33	            return response()->json(['detail' => 'Method Not Allowed'], 405);
34	        });
35	        $exceptions->render(function (HttpExceptionInterface $e, Request $request) {
36	            return response()->json(['detail' => $e->getMessage() ?: 'Error'], $e->getStatusCode(), $e->getHeaders());
37	        });
38	        $exceptions->render(function (Throwable $e, Request $request) {
39	            report($e);
40	
41	            return response()->json(['detail' => 'Internal Server Error'], 500);
