3	namespace App\Http\Middleware;
4	
5	use App\Auth\Jwt;
6	use App\Support\Errors;
7	use App\Support\Guid;
8	use Closure;
9	use Illuminate\Http\Request;
10	use Illuminate\Support\Facades\DB;
11	
12	/**
13	 * mealie/core/dependencies/dependencies.py get_current_user / try_get_current_user / get_admin_user.
14	 *   mealie.user      -> 401 unless a valid user token
15	 *   mealie.admin     -> as above, then 403 unless users.admin
16	 *   mealie.optional  -> sets the user when the token is valid, never fails
17	 */
18	class MealieAuth
19	{
20	    public function handle(Request $request, Closure $next, string $mode = 'user')
21	    {
22	        $user = self::resolve($request);
23	
24	        if ($user === null && $mode !== 'optional') {
25	            Errors::unauthorized();
26	        }
27	        if ($mode === 'admin' && ! $user->admin) {
28	            Errors::http(403, 'Forbidden');
29	        }
30	
31	        $request->attributes->set('mealie_user', $user);
32	
33	        return $next($request);
34	    }
35	
36	    public static function token(Request $request): string
37	    {
38	        $token = $request->bearerToken();
39	        if ($token === null || $token === '') {
40	            $token = (string) $request->cookies->get('mealie.access_token', '');
41	        }
42	
43	        return $token;
44	    }
45	
46	    public static function resolve(Request $request): ?object
47	    {
48	        $token = self::token($request);
49	        if ($token === '') {
50	            return null;
51	        }
52	        $claims = Jwt::decode($token, Jwt::secret());
53	        if ($claims === null) {
54	            return null;
55	        }
56	
57	        $db = DB::connection('mealie');
58	
59	        if (array_key_exists('long_token', $claims)) {
60	            $userId = Guid::toDb((string) ($claims['id'] ?? ''));
61	            $row = $db->table('long_live_tokens')->where('token', $token)->where('user_id', $userId)->first();
62	
63	            return $row ? $db->table('users')->where('id', $row->user_id)->first() : null;
64	        }
65	
66	        $userId = Guid::toDb((string) ($claims['sub'] ?? ''));
67	        if ($userId === null) {
68	            return null;
69	        }
70	        $user = $db->table('users')->where('id', $userId)->first();
71	        if ($user === null) {
72	            return null;
73	        }
74	
75	        if ($user->tokens_valid_after !== null) {
76	            $iat = $claims['iat'] ?? null;
77	            $after = strtotime($user->tokens_valid_after.' UTC');
78	            if (! is_numeric($iat) || $iat < $after) {
79	                return null;
80	            }
81	        }
82	
83	        return $user;
84	    }
85	}
