3	namespace App\Support;
4	
5	use Illuminate\Http\Exceptions\HttpResponseException;
6	
7	/**
8	 * Error bodies as FastAPI produces them for this app.
9	 * - HTTPException:       {"detail": <string|object>}
10	 * - Validation (dev):    {"status_code": 422, "message": <string>, "data": null}  (mealie/routes/handlers.py)
11	 * - HttpRepo errors:     detail = {"message", "error": true, "exception"}         (mealie/schema/response/responses.py)
12	 */
13	class Errors
14	{
15	    public static function http(int $status, mixed $detail = null, array $headers = []): never
16	    {
17	        $detail ??= match ($status) {
18	            400 => 'Bad Request',
19	            401 => 'Unauthorized',
20	            403 => 'Forbidden',
21	            404 => 'Not Found',
22	            405 => 'Method Not Allowed',
23	            409 => 'Conflict',
24	            default => 'Error',
25	        };
26	
27	        throw new HttpResponseException(response()->json(['detail' => $detail], $status, $headers));
28	    }
29	
30	    public static function validation(string $message): never
31	    {
32	        throw new HttpResponseException(response()->json([
33	            'status_code' => 422,
34	            'message' => $message,
35	            'data' => null,
36	        ], 422));
37	    }
38	
39	    /** ErrorResponse.respond(message, exception) wrapped in detail. */
40	    public static function errorResponse(int $status, string $message, ?string $exception = null): never
41	    {
42	        self::http($status, ['message' => $message, 'error' => true, 'exception' => $exception]);
43	    }
44	
45	    public static function unauthorized(): never
46	    {
47	        self::http(401, 'Could not validate credentials', ['WWW-Authenticate' => 'Bearer']);
48	    }
49	}
